# -*- coding: utf-8 -*-
# 7-turkce-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESKİCİ HİKÂYESİ (REFİK HALİT KARAY): İLETİŞİM VE EMPATİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hikâyenin Yapı Unsurları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yazar: Refik Halit Karay (Gurbet Hikâyeleri)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Kişiler: Küçük öksüz/yetim HASAN ve yaşlı</text>\n  <text x="40" y="138" font-size="11" fill="#334155">  ayakkabı tamircisi (eskici) İzmirlili Türk Usta.</text>\n  <text x="40" y="160" font-size="11" fill="#334155">• Mekan: İstanbul\'dan gönderildiği Filistin\'deki</text>\n  <text x="40" y="178" font-size="11" fill="#334155">  halasının evi (Yabancı dil konuşulan uzak diyar).</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">• Tema: Ana dili ve memleket özlemi, iletişim ihtiyacı</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İletişim Açısından Eskici Metninin Analizi</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İletişimsizlik: Hasan çevresindekilerin dilini</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  anlamadığı için içine kapanır ve suskunlaşır.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Dönüm Noktası: Eve gelen eskicinin ağzındaki</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  çivileri çıkarıp Türkçe konuşması ("Çiviler ağzıma</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  batıyor") Hasan\'ın dünyasını aydınlatır.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Ortak Dil (Ana Dili) En Güçlü Sosyal Bağdır!</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESKİCİ HİKÂYESİ (REFİK HALİT KARAY): İLETİŞİM VE EMPATİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hikâyenin Yapı Unsurları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Yazar: Refik Halit Karay (Gurbet Hikâyeleri)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Kişiler: Küçük öksüz/yetim HASAN ve yaşlı</text>\n  <text x="40" y="138" font-size="11" fill="#334155">  ayakkabı tamircisi (eskici) İzmirlili Türk Usta.</text>\n  <text x="40" y="160" font-size="11" fill="#334155">• Mekan: İstanbul\'dan gönderildiği Filistin\'deki</text>\n  <text x="40" y="178" font-size="11" fill="#334155">  halasının evi (Yabancı dil konuşulan uzak diyar).</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">• Tema: Ana dili ve memleket özlemi, iletişim ihtiyacı</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İletişim Açısından Eskici Metninin Analizi</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• İletişimsizlik: Hasan çevresindekilerin dilini</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  anlamadığı için içine kapanır ve suskunlaşır.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Dönüm Noktası: Eve gelen eskicinin ağzındaki</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  çivileri çıkarıp Türkçe konuşması ("Çiviler ağzıma</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  batıyor") Hasan\'ın dünyasını aydınlatır.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Ortak Dil (Ana Dili) En Güçlü Sosyal Bağdır!</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YA HAYIR SÖYLE.. METNİ: İLETİŞİM, NEZAKET VE GÖRGÜ KURALLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Söz Söyleme ve Dinleme Adabı</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Temel İlke: "Ya hayır söyle ya da sus!"</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Kırıcı, alaycı, suçlayıcı ("Sen dili") ifadeler</text>\n  <text x="40" y="138" font-size="11" fill="#334155">  yerine yapıcı ve empatik ("Ben dili") kullanmak.</text>\n  <text x="40" y="162" font-size="11" fill="#334155">• Söz kesmeden göz teması kurarak etkin dinlemek.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Doğruluğu kesinleşmemiş dedikodu ve söylentileri</text>\n  <text x="40" y="204" font-size="11" fill="#334155">  yaymaktan kaçınmak.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Sosyal ve Dijital İletişim Ortamlarında Nezaket</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Yüz Yüze Ortamlar: Selamlaşmak, teşekkür etmek,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  özür dilemek, ses tonunu ve beden dilini ayarlamak.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Dijital Ortamlar (Sosyal Medya / Mesajlaşma):</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  Kişisel mahremiyete saygı duymak, siber zorbalıktan</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  kaçınmak ve Türkçeyi kurallarına uygun kullanmak.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Tatlı Dil Yılanı Deliğinden Çıkarır</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YA HAYIR SÖYLE.. METNİ: İLETİŞİM, NEZAKET VE GÖRGÜ KURALLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Söz Söyleme ve Dinleme Adabı</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Temel İlke: "Ya hayır söyle ya da sus!"</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Kırıcı, alaycı, suçlayıcı ("Sen dili") ifadeler</text>\n  <text x="40" y="138" font-size="11" fill="#334155">  yerine yapıcı ve empatik ("Ben dili") kullanmak.</text>\n  <text x="40" y="162" font-size="11" fill="#334155">• Söz kesmeden göz teması kurarak etkin dinlemek.</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Doğruluğu kesinleşmemiş dedikodu ve söylentileri</text>\n  <text x="40" y="204" font-size="11" fill="#334155">  yaymaktan kaçınmak.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Sosyal ve Dijital İletişim Ortamlarında Nezaket</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Yüz Yüze Ortamlar: Selamlaşmak, teşekkür etmek,</text>\n  <text x="375" y="116" font-size="11" fill="#334155">  özür dilemek, ses tonunu ve beden dilini ayarlamak.</text>\n  <text x="375" y="140" font-size="11" fill="#334155">• Dijital Ortamlar (Sosyal Medya / Mesajlaşma):</text>\n  <text x="375" y="158" font-size="11" fill="#334155">  Kişisel mahremiyete saygı duymak, siber zorbalıktan</text>\n  <text x="375" y="176" font-size="11" fill="#334155">  kaçınmak ve Türkçeyi kurallarına uygun kullanmak.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Tatlı Dil Yılanı Deliğinden Çıkarır</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÜST DÜZEY OKUMA BECERİLERİ: ÇIKARIM, ÇÖZÜMLEME, DEĞERLENDİRME</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Çıkarım ve Çözümleme</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Çıkarım Yapma: Metinde</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  doğrudan söylenmeyen örtük</text>\n  <text x="35" y="134" font-size="11" fill="#334155">  anlama ipuçlarından ulaşmaktır.</text>\n  <text x="35" y="160" font-size="11" fill="#334155">• Çözümleme: Metni yapı,</text>\n  <text x="35" y="178" font-size="11" fill="#334155">  dil, kahraman psikolojisi ve</text>\n  <text x="35" y="196" font-size="11" fill="#334155">  neden-sonuç bağlarıyla ayırmak.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Eleştirme ve Değerlendirme</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Eleştirme: Metnin güçlü ve</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  eksik yönlerini gerekçeleriyle</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  ortaya koymaktır.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• Değerlendirme: Yazarın dil</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  ve anlatım başarısı hakkında</text>\n  <text x="260" y="196" font-size="11" fill="#334155">  ölçütlere dayalı yargıya varmak.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Özetleme Kuralları</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Ana düşünce ve anahtar</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  olaylar korunur; gereksiz</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  ayrıntılar ve örnekler çıkarılır.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Olayların kronolojik sırası</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  bozulmadan kendi cümlelerimizle</text>\n  <text x="485" y="196" font-size="11" fill="#334155">  kısa ve tarafsız yazılır.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÜST DÜZEY OKUMA BECERİLERİ: ÇIKARIM, ÇÖZÜMLEME, DEĞERLENDİRME</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Çıkarım ve Çözümleme</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Çıkarım Yapma: Metinde</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  doğrudan söylenmeyen örtük</text>\n  <text x="35" y="134" font-size="11" fill="#334155">  anlama ipuçlarından ulaşmaktır.</text>\n  <text x="35" y="160" font-size="11" fill="#334155">• Çözümleme: Metni yapı,</text>\n  <text x="35" y="178" font-size="11" fill="#334155">  dil, kahraman psikolojisi ve</text>\n  <text x="35" y="196" font-size="11" fill="#334155">  neden-sonuç bağlarıyla ayırmak.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Eleştirme ve Değerlendirme</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Eleştirme: Metnin güçlü ve</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  eksik yönlerini gerekçeleriyle</text>\n  <text x="260" y="134" font-size="11" fill="#334155">  ortaya koymaktır.</text>\n  <text x="260" y="160" font-size="11" fill="#334155">• Değerlendirme: Yazarın dil</text>\n  <text x="260" y="178" font-size="11" fill="#334155">  ve anlatım başarısı hakkında</text>\n  <text x="260" y="196" font-size="11" fill="#334155">  ölçütlere dayalı yargıya varmak.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Özetleme Kuralları</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Ana düşünce ve anahtar</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  olaylar korunur; gereksiz</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  ayrıntılar ve örnekler çıkarılır.</text>\n  <text x="485" y="160" font-size="11" fill="#334155">• Olayların kronolojik sırası</text>\n  <text x="485" y="178" font-size="11" fill="#334155">  bozulmadan kendi cümlelerimizle</text>\n  <text x="485" y="196" font-size="11" fill="#334155">  kısa ve tarafsız yazılır.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARTIŞMA ANLATIM BİÇİMİ VE DÜŞÜNCEYİ GELİŞTİRME YOLLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tartışmacı Anlatım (Tartışma)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Amaç: Okuyucunun yerleşik bir fikrini değiştirmek</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ve yazarın kendi düşüncesini kabul ettirmektir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Yapı: Önce karşı çıkılan görüş (antitez) verilir,</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ardından yazar kendi savunduğu görüşü (tez) kanıtlar.</text>\n  <text x="40" y="182" font-size="11" font-weight="bold" fill="#1e40af">• Dil İpuçları: "Bence, bana göre, oysa, halbuki,</text>\n  <text x="40" y="200" font-size="11" font-weight="bold" fill="#1e40af">  kanımca, sanıldığının aksine" ve soru cümleleri.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Düşünceyi Geliştirme Yolları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Karşılaştırma: İki kavram/durum arasındaki benzerlik</text>\n  <text x="375" y="114" font-size="11" fill="#334155">  veya farkları ortaya koyma (en, daha, ise, göre).</text>\n  <text x="375" y="136" font-size="11" fill="#334155">• Tanımlama: "Bu nedir?" sorusuna cevap verme.</text>\n  <text x="375" y="158" font-size="11" fill="#334155">• Örneklendirme: Soyut düşünceyi örneklerle somutlama.</text>\n  <text x="375" y="180" font-size="11" fill="#334155">• Tanık Gösterme: Uzman bir kişinin sözünü tırnak</text>\n  <text x="375" y="196" font-size="11" fill="#334155">  içinde doğrudan alıntılama (Örn: Yunus Emre\'nin sözü).</text>\n  <text x="375" y="218" font-size="11" fill="#334155">• Sayısal Verilerden Yararlanma: İstatistik ve oranlar.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TARTIŞMA ANLATIM BİÇİMİ VE DÜŞÜNCEYİ GELİŞTİRME YOLLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tartışmacı Anlatım (Tartışma)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Amaç: Okuyucunun yerleşik bir fikrini değiştirmek</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ve yazarın kendi düşüncesini kabul ettirmektir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• Yapı: Önce karşı çıkılan görüş (antitez) verilir,</text>\n  <text x="40" y="158" font-size="11" fill="#334155">  ardından yazar kendi savunduğu görüşü (tez) kanıtlar.</text>\n  <text x="40" y="182" font-size="11" font-weight="bold" fill="#1e40af">• Dil İpuçları: "Bence, bana göre, oysa, halbuki,</text>\n  <text x="40" y="200" font-size="11" font-weight="bold" fill="#1e40af">  kanımca, sanıldığının aksine" ve soru cümleleri.</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Düşünceyi Geliştirme Yolları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Karşılaştırma: İki kavram/durum arasındaki benzerlik</text>\n  <text x="375" y="114" font-size="11" fill="#334155">  veya farkları ortaya koyma (en, daha, ise, göre).</text>\n  <text x="375" y="136" font-size="11" fill="#334155">• Tanımlama: "Bu nedir?" sorusuna cevap verme.</text>\n  <text x="375" y="158" font-size="11" fill="#334155">• Örneklendirme: Soyut düşünceyi örneklerle somutlama.</text>\n  <text x="375" y="180" font-size="11" fill="#334155">• Tanık Gösterme: Uzman bir kişinin sözünü tırnak</text>\n  <text x="375" y="196" font-size="11" fill="#334155">  içinde doğrudan alıntılama (Örn: Yunus Emre\'nin sözü).</text>\n  <text x="375" y="218" font-size="11" fill="#334155">• Sayısal Verilerden Yararlanma: İstatistik ve oranlar.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİNLERDE SÖZ SANATLARI (EDEBÎ SANATLAR)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Benzetme ve Kişileştirme</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Benzetme (Teşbih): Zayıf</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  olanın güçlüye benzetilmesi</text>\n  <text x="35" y="134" font-size="10.5" fill="#1e40af">  ("Susuz bir çiçek gibi boynunu</text>\n  <text x="35" y="150" font-size="10.5" fill="#1e40af">   büken küçük Hasan").</text>\n  <text x="35" y="174" font-size="11" fill="#334155">• Kişileştirme (Teşhis): İnsana</text>\n  <text x="35" y="192" font-size="11" fill="#334155">  ait özelliği doğaya verme</text>\n  <text x="35" y="208" font-size="10.5" fill="#1e40af">  ("Hüzünlü rüzgâr ağlıyordu").</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Konuşturma ve Abartma</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Konuşturma (İntak): İnsan</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  dışı varlığı konuşturma;</text>\n  <text x="260" y="134" font-size="10.5" fill="#166534">  her intakta kişileştirme de</text>\n  <text x="260" y="150" font-size="10.5" fill="#166534">  vardır.</text>\n  <text x="260" y="174" font-size="11" fill="#334155">• Abartma (Mübalağa): Bir</text>\n  <text x="260" y="192" font-size="11" fill="#334155">  durumu olduğundan çok</text>\n  <text x="260" y="208" font-size="10.5" fill="#166534">  büyük/küçük gösterme ("Gözyaşı sel oldu").</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Karşıtlık (Tezat)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Birbirine zıt kavram veya</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  durumların aynı cümlede</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  bir arada kullanılmasıdır.</text>\n  <text x="485" y="160" font-size="10.5" fill="#92400e">• Örnek: "Ağlarım hatıra</text>\n  <text x="485" y="178" font-size="10.5" fill="#92400e">  geldikçe gülüştüklerimiz"</text>\n  <text x="485" y="196" font-size="10.5" fill="#334155">  (Ağlamak ve gülmek tezat).</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİNLERDE SÖZ SANATLARI (EDEBÎ SANATLAR)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Benzetme ve Kişileştirme</text>\n  <text x="35" y="98" font-size="11" fill="#334155">• Benzetme (Teşbih): Zayıf</text>\n  <text x="35" y="116" font-size="11" fill="#334155">  olanın güçlüye benzetilmesi</text>\n  <text x="35" y="134" font-size="10.5" fill="#1e40af">  ("Susuz bir çiçek gibi boynunu</text>\n  <text x="35" y="150" font-size="10.5" fill="#1e40af">   büken küçük Hasan").</text>\n  <text x="35" y="174" font-size="11" fill="#334155">• Kişileştirme (Teşhis): İnsana</text>\n  <text x="35" y="192" font-size="11" fill="#334155">  ait özelliği doğaya verme</text>\n  <text x="35" y="208" font-size="10.5" fill="#1e40af">  ("Hüzünlü rüzgâr ağlıyordu").</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Konuşturma ve Abartma</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Konuşturma (İntak): İnsan</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  dışı varlığı konuşturma;</text>\n  <text x="260" y="134" font-size="10.5" fill="#166534">  her intakta kişileştirme de</text>\n  <text x="260" y="150" font-size="10.5" fill="#166534">  vardır.</text>\n  <text x="260" y="174" font-size="11" fill="#334155">• Abartma (Mübalağa): Bir</text>\n  <text x="260" y="192" font-size="11" fill="#334155">  durumu olduğundan çok</text>\n  <text x="260" y="208" font-size="10.5" fill="#166534">  büyük/küçük gösterme ("Gözyaşı sel oldu").</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Karşıtlık (Tezat)</text>\n  <text x="485" y="98" font-size="11" fill="#334155">• Birbirine zıt kavram veya</text>\n  <text x="485" y="116" font-size="11" fill="#334155">  durumların aynı cümlede</text>\n  <text x="485" y="134" font-size="11" fill="#334155">  bir arada kullanılmasıdır.</text>\n  <text x="485" y="160" font-size="10.5" fill="#92400e">• Örnek: "Ağlarım hatıra</text>\n  <text x="485" y="178" font-size="10.5" fill="#92400e">  geldikçe gülüştüklerimiz"</text>\n  <text x="485" y="196" font-size="10.5" fill="#334155">  (Ağlamak ve gülmek tezat).</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİL BİLGİSİ: ZARFLAR (BELİRTEÇLER) VE 5 TEMEL TÜRÜ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Zarf Nedir? Hangi Sorularla Bulunur?</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Fiilleri, fiilimsileri, sıfatları veya kendi</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  türünden kelimeleri anlamca belirten sözcüklerdir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• 1. Durum (Hâl) Zarfı: Fiile sorulan "Nasıl?"</text>\n  <text x="40" y="158" font-size="10.5" fill="#1e40af">     ("Eskiciyi SESSİZCE ve DİKKATLE izliyordu.")</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• 2. Zaman Zarfı: Fiile sorulan "Ne zaman?"</text>\n  <text x="40" y="198" font-size="10.5" fill="#1e40af">     ("YARIN sabah vapurla yola çıkacaklar.")</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yer-Yön, Miktar ve Soru Zarfları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• 3. Yer-Yön Zarfı: Fiile sorulan "Nereye?" (Ek almaz!)</text>\n  <text x="375" y="116" font-size="10.5" fill="#166534">     (içeri, dışarı, aşağı, yukarı, ileri, geri, beri, öte)</text>\n  <text x="375" y="138" font-size="11" fill="#334155">• 4. Miktar (Azlık-Çokluk) Zarfı: "Ne kadar?"</text>\n  <text x="375" y="156" font-size="10.5" fill="#166534">     (az, çok, daha, en, pek, oldukça: "ÇOK ağladı")</text>\n  <text x="375" y="178" font-size="11" fill="#334155">• 5. Soru Zarfı: Eylemi soru yoluyla belirtenler</text>\n  <text x="375" y="196" font-size="10.5" fill="#166534">     (Nasıl, ne zaman, niçin, neden, ne diye, ne kadar)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Dikkat: "İçeri girdi" (Zarf) | "İçeriye girdi" (İsim!)</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİL BİLGİSİ: ZARFLAR (BELİRTEÇLER) VE 5 TEMEL TÜRÜ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Zarf Nedir? Hangi Sorularla Bulunur?</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Fiilleri, fiilimsileri, sıfatları veya kendi</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  türünden kelimeleri anlamca belirten sözcüklerdir.</text>\n  <text x="40" y="140" font-size="11" fill="#334155">• 1. Durum (Hâl) Zarfı: Fiile sorulan "Nasıl?"</text>\n  <text x="40" y="158" font-size="10.5" fill="#1e40af">     ("Eskiciyi SESSİZCE ve DİKKATLE izliyordu.")</text>\n  <text x="40" y="180" font-size="11" fill="#334155">• 2. Zaman Zarfı: Fiile sorulan "Ne zaman?"</text>\n  <text x="40" y="198" font-size="10.5" fill="#1e40af">     ("YARIN sabah vapurla yola çıkacaklar.")</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yer-Yön, Miktar ve Soru Zarfları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• 3. Yer-Yön Zarfı: Fiile sorulan "Nereye?" (Ek almaz!)</text>\n  <text x="375" y="116" font-size="10.5" fill="#166534">     (içeri, dışarı, aşağı, yukarı, ileri, geri, beri, öte)</text>\n  <text x="375" y="138" font-size="11" fill="#334155">• 4. Miktar (Azlık-Çokluk) Zarfı: "Ne kadar?"</text>\n  <text x="375" y="156" font-size="10.5" fill="#166534">     (az, çok, daha, en, pek, oldukça: "ÇOK ağladı")</text>\n  <text x="375" y="178" font-size="11" fill="#334155">• 5. Soru Zarfı: Eylemi soru yoluyla belirtenler</text>\n  <text x="375" y="196" font-size="10.5" fill="#166534">     (Nasıl, ne zaman, niçin, neden, ne diye, ne kadar)</text>\n  <text x="517" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Dikkat: "İçeri girdi" (Zarf) | "İçeriye girdi" (İsim!)</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
